def publish_ai_pages(page, cfg):
    date=cfg.get('ai_content_updated','2026-10-02')
    hub_date='2026-10-11'
    def publish(path,title,description,body,lastmod=None):
        page(path,title,description,body,lastmod=lastmod or '2026-10-07')
    cards=''.join(f'<article class="card"><p class="eyebrow">{escape(t["category"])}</p><h3><a href="/ai-tools/{t["slug"]}/">{escape(t["name"])}</a></h3><p>{escape(t["summary"])}</p><a class="arrow" href="/ai-tools/{t["slug"]}/">Read the buying guide →</a></article>' for t in TOOLS)
    rows=''.join(f'<tr><td><a href="/ai-tools/{t["slug"]}/">{escape(t["name"])}</a></td><td>{escape(t["category"])}</td><td>{escape(t["limits"])}</td></tr>' for t in TOOLS)
    meeting_cards=''.join(f'<article class="card"><p class="eyebrow">AI WORKFLOW</p><h3><a href="/ai-tools/{slug}/">{escape(title)}</a></h3><p>{escape(description)}</p></article>' for slug,title,description,_ in MEETING_GUIDES)
    task_routes=(
        '<section class="section" id="task-routes"><div class="section-heading"><h2>Start with the task, then choose a tool</h2><a href="/free-ai/">Compare free entry points →</a></div>'
        '<p>Choose the job below. Each guide shows what to prepare, what to do and how to check the result.</p><div class="grid task-grid">'
        '<article class="card"><p class="eyebrow">WRITE</p><h3><a href="/start/">Turn notes into a draft you can use</a></h3><p>Keep facts, missing details and the action you control separate.</p></article>'
        '<article class="card"><p class="eyebrow">READ A PDF</p><h3><a href="/ai-tools/scanned-pdf-to-text/">Prepare readable document text</a></h3><p>Decide whether OCR is needed, preserve page labels and verify extracted values.</p></article>'
        '<article class="card"><p class="eyebrow">FINISH A FILE</p><h3><a href="/ai-tools/check-free-ai-export/">Save, reopen and edit the result</a></h3><p>Save a sample, reopen it and try the edits you need.</p></article>'
        '<article class="card"><p class="eyebrow">LIMIT REACHED</p><h3><a href="/ai-tools/save-free-ai-progress/">Save progress before access stops</a></h3><p>Save your source notes, checked facts, draft and the next step.</p></article>'
        '<article class="card"><p class="eyebrow">MEETING</p><h3><a href="/ai-tools/ai-meeting-notes/">Make meeting notes your team can use</a></h3><p>Check the recording, correct the notes and save decisions with their owners.</p></article>'
        '<article class="card"><p class="eyebrow">COMPARE PLANS</p><h3><a href="/free-ai/">Check what “free” covers</a></h3><p>Separate a free app, a limited plan, a trial and paid API usage.</p></article>'
        '</div></section>')
    lumo_ad=(
        '<section class="section" id="lumo-affiliate"><p class="eyebrow">AFFILIATE ADVERTISEMENT</p>'
        '<h2>Considering Lumo for your next AI task?</h2>'
        '<p>Review Proton Lumo’s current features, plans and usage limits before choosing an AI assistant.</p>'
        '<p><a class="button" href="https://xmknb.com/g/0crpj4qh4nb059e94582a413d45360/" rel="sponsored noopener">Explore Lumo plans →</a></p>'
        '<p>We may earn a commission on qualifying purchases through this link.</p>'
        '<p>This link uses an affiliate redirect. See our <a href="/privacy/#affiliate-links">privacy policy</a> before following it.</p></section>')
    publish('/ai-tools/','AI tools for writing, documents, meetings and coding | '+cfg['brand'],'Practical AI workflows, free entry points and product guides for everyday tasks.',
        '<section class="page-hero task-hero"><p class="eyebrow">AI TOOLS</p><h1>Choose the task.<br><span>Then choose the tool.</span></h1><p class="lede">What are you trying to finish: a draft, a PDF, a spreadsheet or meeting notes? Start there. Choose a product after you know what the job needs.</p><div class="task-links"><a href="#task-routes">Find a workflow</a><a href="/free-ai/">Compare free access</a><a href="#product-guides">Browse product guides</a></div></section>'
        +task_routes+lumo_ad+
        '<div class="notice">Product listings link directly to official sites. The Lumo advertisement here and advertisements in three workflow guides are labelled and disclosed. We list no verified coupons; a free plan is not a paid-plan discount.</div>'
        '<section class="section" id="product-guides"><div class="section-heading"><h2>Product guides</h2><a href="#task-routes">Back to task routes ↑</a></div><div class="grid">'+cards+MUSE_CARD+'</div></section><section class="section"><h2>Which tool fits the job?</h2><div class="table-wrap"><table><thead><tr><th>Tool</th><th>Use case</th><th>Before you pay</th></tr></thead><tbody>'+rows+'</tbody></table></div></section>'
        '<section class="section"><h2>Meeting notes, transcription and summaries</h2><p>Need a transcript, a summary or a list of decisions? These guides walk through recording, corrections and saving the result.</p><div class="grid">'+meeting_cards+'</div></section>'
        '<section class="prose"><h2>Practical guides</h2><p><a href="/ai-tools/keep-zero-blank-unknown/">Keep zero, blank and UNKNOWN separate in exported tables</a></p><p><a href="/ai-tools/ask-about-missing-details/">Ask one useful follow-up when a detail is missing</a></p><p><a href="/ai-tools/check-ai-source-updates/">Check source versions after a document changes</a></p><p><a href="/ai-tools/check-ai-citations/">Check cited evidence before using an AI answer</a></p><p><a href="/ai-tools/coding-assistant-checklist/">Choose an AI coding assistant without buying overlapping subscriptions</a></p><p><a href="/ai-tools/ai-app-budget/">Plan an AI app budget: tools, hosting and model usage</a></p><p><a href="/ai-tools/check-free-ai-export/">Check a file after exporting it</a></p><p><a href="/ai-tools/save-free-ai-progress/">Save your work before you hit a free usage limit</a></p><h2>How we review</h2><p>Product details come from the official sources linked in each guide. These are buying guides, not performance tests. We update them manually; VPS price checks run separately. Product source review date: '+escape(date)+'. Task hub review date: '+escape(hub_date)+'. Check the official page before purchase.</p></section>',lastmod=hub_date)
    publish_meeting_pages(page,cfg.get('meeting_content_updated','2026-10-03'))
    publish_muse(page)
    for t in TOOLS:
        extra=f'<li><a href="{escape(t["extra"])}" rel="noopener">Official hosting requirements</a></li>' if t.get('extra') else ''
        body=f'<section class="page-hero"><p class="eyebrow">{escape(t["category"])}</p><h1>{escape(t["name"])}: what to check before buying</h1><p class="lede">{escape(t["summary"])}</p></section><article class="prose"><h2>What the plan includes</h2><p>{escape(t["facts"])}</p><h2>Try this before paying</h2><p>{escape(t["advice"])}</p><h2>Check the costs and limits</h2><p>{escape(t["limits"])}</p><h2>Official sources</h2><ul><li><a href="{escape(t["source"])}" rel="noopener">Official product information and terms</a></li>{extra}</ul><p>Source review date: {escape(date)}. Based on product documentation, not a performance test. Source links are not affiliate links.</p><p><a href="/ai-tools/">← All AI tools</a> · <a href="/ai-tools/ai-app-budget/">Plan your project budget</a></p></article>'
